namespace {
size_t checks=0;
void check(bool ok,const char*message){++checks;if(!ok)throw std::runtime_error(message);}
template<class F>bool refuses(F f){try{f();return false;}catch(const std::exception&){return true;}}
Vec3 point(const AffineTransform&t,Vec3 p){auto q=t.point({p.x,p.y,p.z});return {float(q[0]),float(q[1]),float(q[2])};}
float weight(const VertexWeights&row,size_t b){for(auto i:row)if(i.joint==b)return i.weight;return 0;}
HumanLandmarks marks(){
 HumanLandmarks l;l.points={{"hips",{0,1,0}},{"spine",{0,1.25f,0}},{"head",{0,1.7f,0}}};
 for(std::string side:{"left","right"}){float s=side=="left"?1:-1;
 l.points[side+"UpperLeg"]={s*.15f,1,0};l.points[side+"LowerLeg"]={s*.15f,.55f,0};l.points[side+"Foot"]={s*.15f,.1f,0};l.points[side+"Toes"]={s*.15f,.08f,.12f};
 l.points[side+"UpperArm"]={s*.25f,1.5f,0};l.points[side+"LowerArm"]={s*.55f,1.4f,0};l.points[side+"Hand"]={s*.8f,1.3f,0};l.points[side+"ThumbMetacarpal"]={s*.81f,1.3f,-.03f};l.points[side+"ThumbProximal"]={s*.84f,1.3f,-.045f};l.points[side+"ThumbDistal"]={s*.86f,1.3f,-.06f};
 for(std::string name:{"Index","Middle","Ring","Little"}){float z=name=="Index"?-.025f:name=="Middle"?0:name=="Ring"?.025f:.045f;
 l.points[side+name+"Proximal"]={s*.86f,1.3f,z};l.points[side+name+"Intermediate"]={s*.89f,1.3f,z};l.points[side+name+"Distal"]={s*.915f,1.3f,z};}
 }return l;
}
Mesh surface(const HumanLandmarks&l){
 Mesh m;for(const auto&[role,p]:l.points){(void)role;uint32_t v=m.positions.size();m.positions.insert(m.positions.end(),{p+Vec3{-.003f,0,-.003f},p+Vec3{.003f,0,-.003f},p+Vec3{0,.003f,.003f}});float u=float(v/3%8)*.125f+.01f,w=float(v/3/8)*.125f+.01f;m.indices.insert(m.indices.end(),{v,v+1,v+2});m.uv.insert(m.uv.end(),{{u,w},{u+.1f,w},{u+.05f,w+.1f}});}m.normals.assign(m.positions.size(),{0,0,1});m.validate();return m;
}
Scene fixture(const HumanLandmarks&l){Scene s;auto m=surface(l);s.active().painted=std::make_shared<PaintedMesh>(m,64);s.active().mesh_active=true;DeformationState d(m);d.morphs=MorphSet(m);auto edited=m.positions;edited[0].z+=.001f;d.morphs->set_target(m,"retained artist shape",edited);d.morph_weights={.25f};s.set_deformation(1,d);return s;}
void axes(const Skeleton&s,const HumanoidMapping&mapping,const HumanLandmarks&l){auto seg=s.segments();for(std::string side:{"left","right"}){
 auto b=mapping.joints.at(side+"Hand");auto expected=l.points.at(side+"MiddleProximal")-l.points.at(side+"Hand");check(length(seg[b][1]-l.points.at(side+"MiddleProximal"))<2e-6f,"Declared middle base is actual palm endpoint");
 for(std::string name:{"Index","Middle","Ring","Little"}){auto joint=mapping.joints.at(side+name+"Distal");expected=l.points.at(side+name+"Distal")-l.points.at(side+name+"Intermediate");check(dot(normalized(expected),normalized(seg[joint][1]-seg[joint][0]))>.99999f,"Terminal finger continues its own declared phalanx");}
 auto thumb=mapping.joints.at(side+"ThumbDistal");auto thumb_axis=l.points.at(side+"ThumbDistal")-l.points.at(side+"ThumbProximal");check(dot(normalized(thumb_axis),normalized(seg[thumb][1]-seg[thumb][0]))>.99999f,"Terminal thumb continues its own declared phalanx");
 b=mapping.joints.at(side+"Foot");check(length(seg[b][1]-l.points.at(side+"Toes"))<2e-6f,"Declared toe base is actual foot endpoint");
 }}
void analytic(){auto l=marks();auto m=surface(l);auto fit=fit_humanoid(m,l);axes(fit.skeleton,fit.mapping,l);
 // Absent middle must not select an arbitrary thumb/index branch, and absent
 // toes must not continue the shin down through the floor.
 auto missing=l;for(std::string side:{"left","right"}){for(auto role:{"MiddleProximal","MiddleIntermediate","MiddleDistal"})missing.points.erase(side+role);missing.points.erase(side+"Toes");}
 auto partial=fit_humanoid(surface(missing),missing);auto seg=partial.skeleton.segments();for(std::string side:{"left","right"}){auto b=partial.mapping.joints.at(side+"Hand");auto expected=normalized(missing.points.at(side+"Hand")-missing.points.at(side+"LowerArm"));check(dot(normalized(seg[b][1]-seg[b][0]),expected)>.99999f,"Missing middle retains explicit length along forearm continuation, not another finger");check(std::abs(length(seg[b][1]-seg[b][0])-HumanFitOptions{}.terminal_length)<2e-6f,"Missing middle preserves explicit terminal length");b=partial.mapping.joints.at(side+"Foot");check(dot(normalized(seg[b][1]-seg[b][0]),missing.up)>.99999f,"Missing toes preserve previous explicit body-up convention");}
 auto rotated=l;auto rotation=arcball({0,1,0},normalized({.3f,1,.2f}));rotated.up=rotation.rotate(l.up);rotated.left=rotation.rotate(l.left);rotated.front=rotation.rotate(l.front);for(auto&[name,p]:rotated.points){(void)name;p=rotation.rotate(p)+Vec3{.7f,-.2f,.3f};}auto rotated_fit=fit_humanoid(surface(rotated),rotated);axes(rotated_fit.skeleton,rotated_fit.mapping,rotated);
 auto broken=l;broken.points["leftIndexDistal"]=broken.points.at("leftIndexIntermediate");check(refuses([&]{fit_humanoid(surface(broken),broken);}),"Collapsed fingers still refuse rather than invent orientation");
 for(bool mirror:{false,true}){auto scene=fixture(l);std::array<double,16>a{mirror?-1.6:1.6,.12,.06,0,.35,.7,.08,0,.1,.2,1.3,0,1,-.5,.2,1};scene.active().affine_edit=std::make_shared<const NativeAffineEdit>(AffineTransform(a));auto source=scene.encode();auto paint=scene.active().painted;auto deformation=scene.active().deformation;RigFitOptions options;options.fit.terminal_length=.037f;author_humanoid_fit(scene,1,l,options);auto d=scene.active().deformation;axes(*d->skeleton,*d->humanoid,l);auto segments=d->skeleton->segments();auto world=scene.world_matrix(1);
 for(std::string side:{"left","right"})for(auto role:{"ThumbDistal","IndexDistal","MiddleDistal","RingDistal","LittleDistal","Toes"}){auto b=d->humanoid->joints.at(side+role);check(std::abs(length(point(world,segments[b][1])-point(world,segments[b][0]))-.037f)<2e-6f,"Explicit terminal length is independent full-affine world distance on each axis");}
 auto sparse=fixture(missing);sparse.active().affine_edit=scene.active().affine_edit;author_humanoid_fit(sparse,1,missing,options);auto sparse_segments=sparse.active().deformation->skeleton->segments();for(std::string side:{"left","right"})for(auto role:{"Hand","Foot"}){auto b=sparse.active().deformation->humanoid->joints.at(side+role);auto axis=sparse_segments[b][1]-sparse_segments[b][0];auto expected=std::string_view(role)=="Hand"?normalized(missing.points.at(side+"Hand")-missing.points.at(side+"LowerArm")):missing.up;check(dot(normalized(axis),expected)>.99999f&&std::abs(length(point(world,sparse_segments[b][1])-point(world,sparse_segments[b][0]))-.037f)<2e-6f,"Absent optional Middle/Toes preserve declared fallback direction and exact affine world length");}
 check(scene.active().painted==paint&&d->morphs->encode()==deformation->morphs->encode()&&d->morph_weights==deformation->morph_weights,"Affine fitting retains exact paint/geometry and morph source owners/values");auto cancelled=fixture(l);check(refuses([&]{author_humanoid_fit(cancelled,1,l,options,[]{return true;});})&&cancelled.encode()==fixture(l).encode(),"Cancelled fitting retains full original authoring data");
 SkinAuthoringOptions rebind;rebind.reference=1;rebind.falloff=4;rebind.locks.assign(d->skeleton->bones.size(),0);auto locked=d->humanoid->joints.at("leftHand");rebind.locks[locked]=1;auto old=*d->skin;author_skin(scene,1,rebind);auto rebound=scene.active().deformation->skin;size_t positive=0;for(size_t v=0;v<old.vertices.size();++v){check(weight(old.vertices[v],locked)==weight(rebound->vertices[v],locked),"Partial locked influence remains bit-exact during corrected-rig rebind");positive+=weight(old.vertices[v],locked)>0;double sum=0;for(auto i:rebound->vertices[v])sum+=i.weight;check(std::abs(sum-1)<2e-6&&rebound->vertices[v].size()<=4,"Rebound weights normalize with unchanged four-influence cap");}check(positive>0,"Lock evidence contains actual positive hand weights");
 }
 auto scene=fixture(l);auto initial=scene.encode();Document doc;doc.replace(scene);check(doc.wait_mesh(),"Native fitted-hand source publishes");auto source=doc.draft_scene().source;doc.fit_humanoid_rig(l,{},source);auto path=std::filesystem::temp_directory_path()/("dome-anatomical-fit-"+std::to_string(getpid())+".dsculpt");doc.save(path);check(doc.wait_asset()&&doc.frame().state->error.empty(),"Existing ordered worker fits full finger landmarks without new frontend");auto accepted=doc.copy_scene().encode();check(Scene::load(path).encode()==accepted,"Ordered Save/reopen retains actual fitted endpoint");check(doc.undo()&&doc.copy_scene().encode()==initial,"One Undo restores complete source including morph data");check(doc.redo()&&doc.copy_scene().encode()==accepted,"One Redo restores exact fitted field");doc.begin_rig_fit();doc.cancel_rig_fit();check(doc.copy_scene().encode()==accepted,"Shared fitting editor Cancel retains accepted source");std::filesystem::remove(path);
}
struct Original {Mesh mesh;HumanLandmarks landmarks;std::map<std::string,Vec3> tips;};
Original read_original(const std::filesystem::path&path){cgltf_options options{};cgltf_data*raw=nullptr;if(cgltf_parse_file(&options,path.c_str(),&raw)!=cgltf_result_success)throw std::runtime_error("Original cgltf parse");std::unique_ptr<cgltf_data,decltype(&cgltf_free)>data(raw,cgltf_free);if(cgltf_load_buffers(&options,raw,path.c_str())!=cgltf_result_success||cgltf_validate(raw)!=cgltf_result_success)throw std::runtime_error("Original cgltf validation");std::ifstream f(path,std::ios::binary);std::vector<char>bytes((std::istreambuf_iterator<char>(f)),{});uint32_t len=0;memcpy(&len,bytes.data()+12,4);auto json=nlohmann::json::parse(bytes.data()+20,bytes.data()+20+len);Original out;
 for(const auto&entry:json.at("extensions").at("VRM").at("humanoid").at("humanBones")){std::string role=entry.at("bone");if(role.ends_with("ThumbProximal"))role.replace(role.size()-8,8,"Metacarpal");else if(role.ends_with("ThumbIntermediate"))role.replace(role.size()-12,12,"Proximal");size_t n=entry.at("node");float m[16];cgltf_node_transform_world(raw->nodes+n,m);out.landmarks.points[role]={m[12],m[13],m[14]};if(role.ends_with("Distal")&&raw->nodes[n].children_count==1){cgltf_node_transform_world(raw->nodes[n].children[0],m);out.tips[role]={m[12],m[13],m[14]};}}
 auto&l=out.landmarks;l.up=normalized(l.points.at("head")-l.points.at("hips"));auto left=l.points.at("leftUpperArm")-l.points.at("rightUpperArm");l.left=normalized(left-l.up*dot(left,l.up));l.front=cross(l.left,l.up);
 for(size_t n=0;n<raw->nodes_count;++n)if(auto*mesh=raw->nodes[n].mesh){float world[16];cgltf_node_transform_world(raw->nodes+n,world);for(size_t p=0;p<mesh->primitives_count;++p){auto&primitive=mesh->primitives[p];auto*position=cgltf_find_accessor(&primitive,cgltf_attribute_type_position,0);auto*normal=cgltf_find_accessor(&primitive,cgltf_attribute_type_normal,0);if(!position||!normal||normal->count!=position->count||primitive.type!=cgltf_primitive_type_triangles||!primitive.indices)throw std::runtime_error("Original triangle domain");uint32_t start=out.mesh.positions.size();for(size_t v=0;v<position->count;++v){float q[3];if(!cgltf_accessor_read_float(position,v,q,3))throw std::runtime_error("Original POSITION read");out.mesh.positions.push_back({world[0]*q[0]+world[4]*q[1]+world[8]*q[2]+world[12],world[1]*q[0]+world[5]*q[1]+world[9]*q[2]+world[13],world[2]*q[0]+world[6]*q[1]+world[10]*q[2]+world[14]});if(!cgltf_accessor_read_float(normal,v,q,3))throw std::runtime_error("Original NORMAL read");Vec3 x{world[0],world[1],world[2]},y{world[4],world[5],world[6]},z{world[8],world[9],world[10]};float determinant=dot(x,cross(y,z));if(std::abs(determinant)<1e-10f)throw std::runtime_error("Original singular normal frame");out.mesh.normals.push_back(normalized((cross(y,z)*q[0]+cross(z,x)*q[1]+cross(x,y)*q[2])/determinant));}for(size_t c=0;c<primitive.indices->count;++c)out.mesh.indices.push_back(start+cgltf_accessor_read_index(primitive.indices,c));}}
 out.mesh.validate();return out;
}
void original(const std::filesystem::path&path){auto source=read_original(path);auto&mesh=source.mesh;auto&l=source.landmarks;HumanFitOptions options;options.maximum_surface_distance=.3f;auto fit=fit_humanoid(mesh,l,options);axes(fit.skeleton,fit.mapping,l);auto segments=fit.skeleton.segments();auto weights=automatic_bind(mesh,fit.skeleton);weights.validate(mesh.positions.size(),fit.skeleton.bones.size());check(l.points.size()==54&&mesh.positions.size()>90000&&mesh.indices.size()>40000,"Full original CC0 arrays and original semantic heads consumed without dropping unused vertices");
 for(std::string role:{"leftIndexDistal","rightIndexDistal","leftMiddleDistal","rightMiddleDistal"}){auto b=fit.mapping.joints.at(role);auto reference=source.tips.at(role)-l.points.at(role);check(dot(normalized(reference),normalized(segments[b][1]-segments[b][0]))>.999f,"Fitted distal axis agrees with independent original VRoid end node");std::set<uint32_t>vertices(mesh.indices.begin(),mesh.indices.end());double sum=0;size_t count=0;for(auto v:vertices)if(length(mesh.positions[v]-source.tips.at(role))<.009f){sum+=weight(weights.vertices[v],b);++count;}check(count>=30&&sum/count>.7,"Real visible fingertip vertices receive meaningful distal support from unchanged solver");std::cout<<path.filename()<<' '<<role<<" fingertip_vertices="<<count<<" mean_distal_weight="<<sum/count<<'\n';
 // Independent Rodrigues/LBS oracle for one terminal bend, without reusing
 // native skin matrix generation or triangle-normal reconstruction.
 auto pose=std::vector<JointTransform>{};for(auto&bone:fit.skeleton.bones)pose.push_back(bone.rest);constexpr float angle=.45f;pose[b].rotation=pose[b].rotation*Quat{std::cos(angle/2),std::sin(angle/2),0,0};auto deformed=deform_mesh(mesh,weights,fit.skeleton,pose);auto world=fit.skeleton.world();Vec3 axis=normalized({world[b][0],world[b][1],world[b][2]}),head=segments[b][0];auto rotate=[&](Vec3 q){return q*std::cos(angle)+cross(axis,q)*std::sin(angle)+axis*dot(axis,q)*(1-std::cos(angle));};double max_error=0,max_normal_error=0;for(auto v:vertices){float w=weight(weights.vertices[v],b);auto expected=mesh.positions[v]*(1-w)+(head+rotate(mesh.positions[v]-head))*w;auto normal=normalized(mesh.normals[v]*(1-w)+rotate(mesh.normals[v])*w);max_error=std::max(max_error,double(length(expected-deformed.positions[v])));max_normal_error=std::max(max_normal_error,double(length(normal-deformed.normals[v])));}check(max_error<3e-5&&max_normal_error<3e-5,"Actual native bend positions and authored normal transport match independent rotation/weight oracle");
 }
}
}
int main(int argc,char**argv)try{if(argc!=2)throw std::invalid_argument("Usage: rig-fit-anatomical-test path/to/assets/humanoid");analytic();for(auto sex:{"female","male"})original(std::filesystem::path(argv[1])/"vroid"/(std::string("base-")+sex+".vrm"));std::cout<<"PASS "<<checks<<" anatomical fitting, actual CC0 support, deformation, affine, locks and history checks\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
